# This is the conflict handling part of the project
# Reserve simultaneous movements before committing positions
# Partly generated by AI


import random
import z3



def resolve_timestep(proposals, speeds, rng: random.Random):
    """Reserve realized next cells atomically, including drift and swept paths.

    Higher route priorities are checked first. A seeded shuffle orders equal-priority
    contenders. Priority cannot evict a stationary vehicle or permit a swap.
    All grant variables are solved together. no position is committed here.
    """

    ids = sorted(proposals)
    if len({tuple(proposals[k]['current']) for k in ids}) != len(ids):
        raise ValueError('Carriers must occupy distinct cells before a timestep')

    # same solve/model pattern as z3 lab verfier.
    solver = z3.Solver()
    grants = {k: z3.Bool('move_' + k) for k in ids}
    x, y = {}, {}

    for k in ids:
        current, destination = proposals[k]['current'], proposals[k]['destination']
        if tuple(current) == tuple(destination):
            solver.add(z3.Not(grants[k]))
        x[k] = z3.If(grants[k], destination[0], current[0])
        y[k] = z3.If(grants[k], destination[1], current[1])

    for index, a in enumerate(ids):
        for b in ids[index+1:]:
            solver.add(z3.Or(x[a] != x[b], y[a] != y[b]))
            pa, pb = proposals[a], proposals[b]
            path_a = set(map(tuple, pa.get('path', [pa['destination']]))) - {tuple(pa['current'])}
            path_b = set(map(tuple, pb.get('path', [pb['destination']]))) - {tuple(pb['current'])}
            if path_a & path_b:
                solver.add(z3.Not(z3.And(grants[a], grants[b])))
            if tuple(pb['current']) in path_a:
                solver.add(z3.Implies(grants[a], grants[b]))
            if tuple(pa['current']) in path_b:
                solver.add(z3.Implies(grants[b], grants[a]))
            if tuple(pa['destination']) == tuple(pb['current']) and tuple(pb['destination']) == tuple(pa['current']):
                solver.add(z3.Not(z3.And(grants[a], grants[b])))
    order = list(ids)
    rng.shuffle(order)  # a little tie-break before sorting by speed
    order.sort(key=lambda k: -speeds[k])

    for k in order:
        solver.push()
        solver.add(grants[k])
        possible = solver.check() == z3.sat
        solver.pop()
        solver.add(grants[k] if possible else z3.Not(grants[k]))
    if solver.check() != z3.sat:
        raise RuntimeError('No safe joint timestep exists')
    model = solver.model()
    granted = {k: z3.is_true(model.eval(grants[k])) for k in ids}
    return {'status': 'SATISFIABLE', 'granted': granted, 'priority_order': order,
            'positions': {k: tuple(proposals[k]['destination'] if granted[k] else proposals[k]['current']) for k in ids}}
